import { Entity, PrimaryColumn, Column, CreateDateColumn, ManyToOne, JoinColumn } from 'typeorm';
import { User } from './user.entity';
import { AccessLevel } from '../../../common/types';

/**
 * One invitation from the owner. The link the owner hands over carries a secret
 * the server never sees; only a hash of a token derived from it is stored. The
 * row outlives acceptance until the owner's client has verified the new keys.
 */
@Entity('user_invites')
export class UserInvite {
  /** Generated by the owner's client: `ownerSecretEncrypted` is bound to it. */
  @PrimaryColumn('uuid')
  id: string;

  /** The id the new user will have. */
  @Column({ name: 'user_id', type: 'uuid', unique: true })
  userId: string;

  @Column({ type: 'varchar', length: 32, unique: true })
  username: string;

  @Column({ name: 'access_level', type: 'enum', enum: AccessLevel, enumName: 'users_access_level_enum', default: AccessLevel.LIMITED })
  accessLevel: AccessLevel;

  /** SHA-256 (hex) of the token the invitee presents. */
  @Column({ name: 'token_hash', type: 'varchar', length: 64 })
  tokenHash: string;

  /** The link's secret, sealed to the owner's own public key so their client can check the binding later. */
  @Column({ name: 'owner_secret_encrypted', type: 'text' })
  ownerSecretEncrypted: string;

  /** HMAC by the invitee over their id, username and public keys, keyed from the link's secret. */
  @Column({ name: 'key_binding', type: 'text', nullable: true })
  keyBinding: string | null;

  @Column({ name: 'created_by', type: 'uuid' })
  createdBy: string;

  @ManyToOne(() => User, { onDelete: 'CASCADE' })
  @JoinColumn({ name: 'created_by' })
  creator: User;

  @Column({ name: 'expires_at', type: 'timestamptz' })
  expiresAt: Date;

  @Column({ name: 'used_at', type: 'timestamptz', nullable: true })
  usedAt: Date | null;

  @CreateDateColumn({ name: 'created_at', type: 'timestamptz' })
  createdAt: Date;
}
